/**
 * Геометрия принятых моделей набора Minotauro Low Poly by Zero (license not stated on the asset page; attribution retained in assets/LICENSES.md, см. assets/LICENSES.md),
 * запечённая по §6.1: без текстур, цвет — слот палитры на треугольник.
 * Позиции упакованы в 16 бит на ось в габаритах модели (min/max).
 */
export interface MinotaurModel {
  readonly tris: number;
  readonly verts: number;
  /** Габарит позы привязки: в нём квантованы позиции. */
  readonly min: readonly [number, number, number];
  readonly max: readonly [number, number, number];
  /** base64 Int16Array: 3 числа на вершину. */
  readonly pos: string;
  /** base64 Uint16Array: 3 индекса на треугольник. */
  readonly idx: string;
  /** base64 Uint8Array: индекс в MINOTAUR_SLOTS, один на треугольник.
   *  Вершина ломается по слоту, поэтому цвет вершины — цвет её треугольника. */
  readonly slot: string;
}

/** Порядок слотов — контракт с render/palette.ts. */
export const MINOTAUR_SLOTS = [
  'сукно-тень',
  'краска-алая',
  'земля',
  'дерево-тень',
  'дерево',
  'дерево-свет',
  'соль-тень',
  'соль',
  'соль-свет',
  'иней',
] as const;

export const MINOTAUR_MODELS = {
  'Minotaur': {
    tris: 3985,
    verts: 8191,
    min: [-0.709, -0.001, -0.354],
    max: [0.709, 2.196, 0.357],
    pos: '',
    idx: '',
    slot: '',
  },
} satisfies Record<string, MinotaurModel>;

export type MinotaurModelName = keyof typeof MINOTAUR_MODELS;
